     fn bell_prefix(&self) -> &'static str {
         if self.pending_bell.replace(false) {
             "\u{7}"
         } else {
             ""
         }
     }
+
+    fn render_prefix(&self) -> String {
+        let mut prefix = String::new();
+        prefix.push_str(self.bell_prefix());
+        if let Some(sequence) = self.pending_clipboard.borrow_mut().take() {
+            prefix.push_str(&sequence);
+        }
+        prefix
+    }
+
+    fn queue_clipboard_copy(&self, text: &str) {
+        *self.pending_clipboard.borrow_mut() = Some(osc52_clipboard_sequence(text));
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey, right_content: &str) -> Vec<UiAction> {
+        let selection = match self.visual_selection {
+            Some(selection) => selection,
+            None => {
+                self.mode = UiMode::Command;
+                return Vec::new();
+            }
+        };
+        let lines = self.pane_lines_for_interaction(selection.focus, right_content);
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                Vec::new()
+            }
+            UiKey::Char('v') => {
+                if selection.kind == VisualKind::Character {
+                    self.clear_visual_selection();
+                } else {
+                    self.set_visual_kind(VisualKind::Character);
+                }
+                Vec::new()
+            }
+            UiKey::Char('V') => {
+                self.set_visual_kind(VisualKind::Line);
+                Vec::new()
+            }
+            UiKey::CtrlV => {
+                self.set_visual_kind(VisualKind::Block);
+                Vec::new()
+            }
+            UiKey::Char('y') => self.copy_visual_selection(right_content, None),
+            UiKey::Char('Y') => self.copy_visual_selection(right_content, Some(VisualKind::Line)),
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1, &lines);
+                Vec::new()
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1, &lines);
+                Vec::new()
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0, &lines);
+                Vec::new()
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0, &lines);
+                Vec::new()
+            }
+            _ => Vec::new(),
+        }
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let position = self.current_text_position(right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            focus: self.focus,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        self.mode = kind.mode();
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+        if self.mode.is_visual() {
+            self.mode = UiMode::Command;
+        }
+    }
+
+    fn set_visual_kind(&mut self, kind: VisualKind) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        }
+        self.mode = kind.mode();
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, lines: &[String]) {
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        let next = TextPosition {
+            row: selection.cursor.row.saturating_add_signed(row_delta),
+            column: selection.cursor.column.saturating_add_signed(column_delta),
+        };
+        selection.cursor = clamp_text_position(next, lines);
+    }
+
+    fn copy_current_line(
+        &mut self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        let lines = self.pane_lines_for_interaction(self.focus, right_content);
+        if lines.is_empty() {
+            return Vec::new();
+        }
+        let position = self.current_text_position(right_content, right_cursor_column);
+        let text = lines[position.row].clone();
+        self.queue_clipboard_copy(&text);
+        vec![UiAction::CopySelection(text)]
+    }
+
+    fn copy_visual_selection(
+        &mut self,
+        right_content: &str,
+        forced_kind: Option<VisualKind>,
+    ) -> Vec<UiAction> {
+        let Some(selection) = self.visual_selection else {
+            return Vec::new();
+        };
+        let lines = self.pane_lines_for_interaction(selection.focus, right_content);
+        let kind = forced_kind.unwrap_or(selection.kind);
+        let text = selected_text(selection, kind, &lines);
+        self.clear_visual_selection();
+        if text.is_empty() {
+            return Vec::new();
+        }
+        self.queue_clipboard_copy(&text);
+        vec![UiAction::CopySelection(text)]
+    }
+
+    fn current_text_position(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        let lines = self.pane_lines_for_interaction(self.focus, right_content);
+        if lines.is_empty() {
+            return TextPosition { row: 0, column: 0 };
+        }
+        let row = match self.focus {
+            PaneFocus::Left => self.control_selected.min(lines.len().saturating_sub(1)),
+            PaneFocus::Right => lines.len().saturating_sub(1),
+        };
+        let column = match self.focus {
+            PaneFocus::Left => 0,
+            PaneFocus::Right => right_cursor_column.unwrap_or_else(|| char_count(&lines[row])),
+        };
+        clamp_text_position(TextPosition { row, column }, &lines)
+    }
+
+    fn pane_lines_for_interaction(&self, focus: PaneFocus, right_content: &str) -> Vec<String> {
+        match focus {
+            PaneFocus::Left => self.left_pane_lines(),
+            PaneFocus::Right => text_lines(&self.visible_right_content(right_content)),
+        }
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let (inner_x, inner_y, inner_width, inner_height, lines) = match selection.focus {
+            PaneFocus::Left if self.left_visible => {
+                let layout = self.layout();
+                (
+                    1,
+                    1,
+                    layout.left_width.saturating_sub(2).max(1),
+                    self.height.saturating_sub(3).max(1),
+                    self.left_pane_lines(),
+                )
+            }
+            PaneFocus::Right => {
+                let layout = self.layout();
+                (
+                    layout.left_width.saturating_add(1),
+                    1,
+                    layout.right_width.saturating_sub(2).max(1),
+                    self.height.saturating_sub(3).max(1),
+                    text_lines(right_content),
+                )
+            }
+            PaneFocus::Left => return,
+        };
+        reverse_selection_cells(
+            buffer,
+            selection,
+            &lines,
+            inner_x,
+            inner_y,
+            inner_width,
+            inner_height,
+        );
+    }

