 fn truncate_to_width(text: &str, width: usize) -> String {
     text.chars().take(width).collect()
 }
+
+fn text_lines(content: &str) -> Vec<String> {
+    content.lines().map(str::to_string).collect()
+}
+
+fn char_count(text: &str) -> usize {
+    text.chars().count()
+}
+
+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+    let row = position.row.min(lines.len() - 1);
+    TextPosition {
+        row,
+        column: position.column.min(char_count(&lines[row])),
+    }
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn selected_text(selection: VisualSelection, kind: VisualKind, lines: &[String]) -> String {
+    match kind {
+        VisualKind::Character => selected_character_text(selection, lines),
+        VisualKind::Line => selected_line_text(selection, lines),
+        VisualKind::Block => selected_block_text(selection, lines),
+    }
+}
+
+fn selected_character_text(selection: VisualSelection, lines: &[String]) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+    let (start, end) = ordered_positions(
+        clamp_text_position(selection.anchor, lines),
+        clamp_text_position(selection.cursor, lines),
+    );
+    (start.row..=end.row)
+        .map(|row| {
+            let line = &lines[row];
+            let start_column = if row == start.row { start.column } else { 0 };
+            let end_column = if row == end.row {
+                end.column.saturating_add(1)
+            } else {
+                char_count(line)
+            };
+            char_range(line, start_column, end_column)
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selected_line_text(selection: VisualSelection, lines: &[String]) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+    let start = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+    let end = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+    lines[start..=end].join("\n")
+}
+
+fn selected_block_text(selection: VisualSelection, lines: &[String]) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+    let start_row = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+    let end_row = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection.anchor.column.max(selection.cursor.column);
+    (start_row..=end_row)
+        .map(|row| char_range(&lines[row], start_column, end_column.saturating_add(1)))
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn char_range(line: &str, start: usize, end: usize) -> String {
+    let start = start.min(char_count(line));
+    let end = end.min(char_count(line));
+    line.chars().skip(start).take(end.saturating_sub(start)).collect()
+}
+
+fn reverse_selection_cells(
+    buffer: &mut Buffer,
+    selection: VisualSelection,
+    lines: &[String],
+    inner_x: u16,
+    inner_y: u16,
+    inner_width: u16,
+    inner_height: u16,
+) {
+    if lines.is_empty() || inner_width == 0 || inner_height == 0 {
+        return;
+    }
+    match selection.kind {
+        VisualKind::Character => {
+            let (start, end) = ordered_positions(
+                clamp_text_position(selection.anchor, lines),
+                clamp_text_position(selection.cursor, lines),
+            );
+            for row in start.row..=end.row {
+                let line = &lines[row];
+                let start_column = if row == start.row { start.column } else { 0 };
+                let end_column = if row == end.row {
+                    end.column.saturating_add(1)
+                } else {
+                    char_count(line)
+                };
+                reverse_character_range(
+                    buffer,
+                    lines,
+                    row,
+                    start_column,
+                    end_column,
+                    inner_x,
+                    inner_y,
+                    inner_width,
+                    inner_height,
+                );
+            }
+        }
+        VisualKind::Line => {
+            let start = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+            let end = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+            for row in start..=end {
+                reverse_visual_line(buffer, lines, row, inner_x, inner_y, inner_width, inner_height);
+            }
+        }
+        VisualKind::Block => {
+            let start_row = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+            let end_row = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+            let start_column = selection.anchor.column.min(selection.cursor.column);
+            let end_column = selection.anchor.column.max(selection.cursor.column);
+            for row in start_row..=end_row {
+                reverse_character_range(
+                    buffer,
+                    lines,
+                    row,
+                    start_column,
+                    end_column.saturating_add(1),
+                    inner_x,
+                    inner_y,
+                    inner_width,
+                    inner_height,
+                );
+            }
+        }
+    }
+}
+
+fn reverse_visual_line(
+    buffer: &mut Buffer,
+    lines: &[String],
+    row: usize,
+    inner_x: u16,
+    inner_y: u16,
+    inner_width: u16,
+    inner_height: u16,
+) {
+    let start_row = visual_start_row(lines, row, inner_width);
+    let rows = visual_row_count(&lines[row], inner_width);
+    for visual_row in start_row..start_row.saturating_add(rows) {
+        if visual_row >= usize::from(inner_height) {
+            break;
+        }
+        for column in 0..inner_width {
+            reverse_cell(buffer, inner_x.saturating_add(column), inner_y.saturating_add(visual_row as u16));
+        }
+    }
+}
+
+fn reverse_character_range(
+    buffer: &mut Buffer,
+    lines: &[String],
+    row: usize,
+    start_column: usize,
+    end_column: usize,
+    inner_x: u16,
+    inner_y: u16,
+    inner_width: u16,
+    inner_height: u16,
+) {
+    let line_len = char_count(&lines[row]);
+    let start_column = start_column.min(line_len);
+    let end_column = end_column.min(line_len);
+    let start_row = visual_start_row(lines, row, inner_width);
+    for column in start_column..end_column.max(start_column.saturating_add(1)) {
+        let visual_row = start_row.saturating_add(column / usize::from(inner_width));
+        if visual_row >= usize::from(inner_height) {
+            break;
+        }
+        let visual_column = column % usize::from(inner_width);
+        reverse_cell(
+            buffer,
+            inner_x.saturating_add(visual_column as u16),
+            inner_y.saturating_add(visual_row as u16),
+        );
+    }
+}
+
+fn visual_start_row(lines: &[String], row: usize, width: u16) -> usize {
+    lines
+        .iter()
+        .take(row)
+        .map(|line| visual_row_count(line, width))
+        .sum()
+}
+
+fn reverse_cell(buffer: &mut Buffer, x: u16, y: u16) {
+    if x < buffer.area.width && y < buffer.area.height {
+        buffer.get_mut(x, y).modifier.insert(Modifier::REVERSED);
+    }
+}
+
+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = chunk.get(1).copied().unwrap_or(0);
+        let third = chunk.get(2).copied().unwrap_or(0);
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}

